refentry.refsect1:
&reftitle.description;
boolftp_rename FTP\Connectionftp stringfrom stringto
ftp_rename rinomina un file o una directory sul server FTP.

&reftitle.returnvalues;


 &return.success; In caso di errore (ad esempio se si tenta di rinominare un file
 inesistente), verrà emesso un errore E_WARNING.

  &reftitle.examples;



    Esempio di ftp_rename


<?php
$old_file = 'somefile.txt.bak';
$new_file = 'somefile.txt';

// Stabilisce la connessione
$ftp = ftp_connect($ftp_server);

// Si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

// Prova a rinominare $old_file in $new_file
if (ftp_rename($ftp, $old_file, $new_file)) {
    echo "$old_file rinominato correttamente in $new_file\n";
} else {
    echo "Si è verificato un problema durante la ridenominazione di $old_file in $new_file\n";
}

// Chiude la connessione
ftp_close($ftp);

?>
